"; geçerli olan hastanenin protokolüdür ve her değişiklik denetim kaydına yazılır. Gerçek üründe bugün: {#} / {#} / {#} zinciri motorun kodunda yazılı ama canlı hatta bağlı değil; canlıda tek basamak var ({#}. dk hekime). Telefona bildirim ve kritik laboratuvar akışı henüz yok.": {
"AZ": "; qüvvədə olan xəstəxananın protokoludur və hər dəyişiklik audit jurnalına yazılır. Real məhsulda bu gün: {#} / {#} / {#} zənciri mühərrikin kodunda yazılıb, lakin canlı xəttə qoşulmayıb; canlıda yalnız bir pillə var ({#}. dəq həkimə). Telefona bildiriş və kritik laboratoriya axını hələ yoxdur.",
"EN": "; the hospital's protocol is what applies, and every change is written to the audit log. In the real product today: the {#} / {#} / {#} chain is written in the engine code but not wired to the live line; live there is a single step (physician at min {#}). Phone notifications and the critical lab flow do not exist yet.",
"RU": "; действует протокол больницы, и каждое изменение записывается в журнал аудита. В реальном продукте сейчас: цепочка {#} / {#} / {#} прописана в коде движка, но не подключена к рабочему контуру; в работе одна ступень ({#}-я мин — врачу). Уведомлений на телефон и потока критических лабораторных результатов пока нет."
},
