"Liste görünümünde tamamlanan işler gizlidir; ızgarada görünür.": {
"AZ": "Siyahı görünüşündə tamamlanan işlər gizlidir; şəbəkədə görünür.",
"EN": "Completed tasks are hidden in list view; visible in the grid.",
"RU": "В режиме списка выполненные задачи скрыты; в сетке они видны."
},
"Liste ön kabul kayıtlarıyla güncellenir. Kimlik ve yatış planı hastane kaydından gelir; burada yalnız yatak atanır.": {
"AZ": "Siyahı qəbul şöbəsinin qeydləri ilə yenilənir. Şəxsiyyət və yerləşdirmə planı xəstəxana qeyd sistemindən gəlir; burada yalnız çarpayı təyin edilir.",
"EN": "The list updates from pre-admission records. Identity and admission plan come from the hospital record; only the bed is assigned here.",
"RU": "Список обновляется данными приёмного отделения. Личные данные и план госпитализации поступают из больничной системы; здесь только назначается койка."
},
"Listeden hasta seçin. Normalde transfer ve taburcu hastane kaydından gelir; bu ekran hastane kaydına ulaşılamadığında kullanılır ve işlem hastane kaydına sonradan bildirilir.": {
"AZ": "Siyahıdan xəstə seçin. Adətən köçürmə və çıxarılma xəstəxana qeydindən gəlir; bu ekran ona çatmaq mümkün olmadıqda istifadə olunur və əməliyyat sonradan xəstəxana qeydinə bildirilir.",
"EN": "Select a patient from the list. Transfers and discharges normally come from the hospital record; this screen is used when it cannot be reached, and the action is reported to the hospital record afterwards.",
"RU": "Выберите пациента из списка. Обычно переводы и выписки поступают из больничной записи; этот экран используется, когда она недоступна, и операция позже передаётся в больничную запись."
},
