"Uygulama kapalıyken bildirim ulaşmaz. Telefona bildirim için karar gerekiyor: bildirim hastane dışındaki bir servisten geçer, bu yüzden içeriğinde hasta bilgisi olmamalı.": {
"AZ": "Tətbiq bağlı olanda bildiriş çatmır. Telefona bildiriş üçün qərar lazımdır: bildiriş xəstəxanadan kənar bir xidmətdən keçir, buna görə də məzmununda xəstə məlumatı olmamalıdır.",
"EN": "Notifications are not delivered while the app is closed. Phone notifications need a decision: they pass through a service outside the hospital, so they must not contain patient data.",
"RU": "При закрытом приложении уведомления не доставляются. Для уведомлений на телефон требуется решение: они проходят через внешний по отношению к больнице сервис, поэтому не должны содержать данных пациента."
},
"Uygulama: {#}) Hastayı gözle (uyanık / huzursuz / ajite → {#} … +{#}). {#}) Uyanık değilse adıyla seslen, gözlerini açıp bakmasını iste (−{#} … −{#}). {#}) Sese yanıt yoksa omzunu sars ya da sternumu ov (−{#} / −{#}).": {
"AZ": "İcra: {#}) Xəstəni müşahidə edin (oyaq / narahat / ajitasiyalı → {#} … +{#}). {#}) Oyaq deyilsə, adı ilə çağırın, gözlərini açıb baxmasını xahiş edin (−{#} … −{#}). {#}) Səsə cavab yoxdursa, çiynini silkələyin və ya döş sümüyünü ovuşdurun (−{#} / −{#}).",
"EN": "Procedure: {#}) Observe the patient (alert / restless / agitated → {#} … +{#}). {#}) If not alert, call by name and ask to open eyes and look at you (−{#} … −{#}). {#}) If no response to voice, shake the shoulder or rub the sternum (−{#} / −{#}).",
"RU": "Порядок: {#}) Наблюдайте за пациентом (бодрствует / беспокоен / возбуждён → {#} … +{#}). {#}) Если не бодрствует, окликните по имени, попросите открыть глаза и посмотреть (−{#} … −{#}). {#}) Если нет ответа на голос, потрясите за плечо или потрите грудину (−{#} / −{#})."
},
