  "Kurulum notu: bu ekran GET /api/admin/health uç noktasından {#} saniyede bir beslenir → { checkedAt, items:[{ key, name, status: ok|warn|down, detail, metrics, lastCheck, ms }] }. Eşikler (ör. HBYS yanıtı {#} ms üstü = uyarı) sunucu yapılandırmasındadır. Ayrıntı: /api/admin/health/:key/history.": {
    AZ:"Quraşdırma qeydi: bu ekran hər {#} saniyədən bir GET /api/admin/health ucundan qidalanır → { checkedAt, items:[{ key, name, status: ok|warn|down, detail, metrics, lastCheck, ms }] }. Hədlər (məs. HBYS cavabı {#} ms-dən çox = xəbərdarlıq) server konfiqurasiyasındadır. Ətraflı: /api/admin/health/:key/history.",
    RU:"Заметка по настройке: экран обновляется каждые {#} с из GET /api/admin/health → { checkedAt, items:[{ key, name, status: ok|warn|down, detail, metrics, lastCheck, ms }] }. Пороги (напр. ответ HBYS больше {#} мс = предупреждение) задаются в конфигурации сервера. Подробности: /api/admin/health/:key/history.",
    EN:"Setup note: this screen is fed from GET /api/admin/health every {#} seconds → { checkedAt, items:[{ key, name, status: ok|warn|down, detail, metrics, lastCheck, ms }] }. Thresholds (e.g. HIS response over {#} ms = warning) live in the server configuration. Detail: /api/admin/health/:key/history." },
