  "Oral / enteral": { AZ:"Oral / enteral", RU:"Перорально / энтерально", EN:"Oral / enteral" },
  "Kaynak: aşağıdaki sıvı izlem ızgarası (pompa + hemşire girişi ve Aldığı–çıkardığı formu) · son giriş": { AZ:"Mənbə: aşağıdakı maye izləmə cədvəli (pompa + tibb bacısı qeydi və qəbul–xaric forması) · son qeyd", RU:"Источник: таблица учёта жидкости ниже (помпа + записи медсестры и форма «поступление–выведение») · последняя запись", EN:"Source: the fluid chart below (pump + nurse entries and the intake–output form) · last entry" },
  "Kaynak: aşağıdaki sıvı izlem ızgarası (pompa + hemşire girişi ve Aldığı–çıkardığı formu) · son giriş —": { AZ:"Mənbə: aşağıdakı maye izləmə cədvəli (pompa + tibb bacısı qeydi və qəbul–xaric forması) · son qeyd —", RU:"Источник: таблица учёта жидкости ниже (помпа + записи медсестры и форма «поступление–выведение») · последняя запись —", EN:"Source: the fluid chart below (pump + nurse entries and the intake–output form) · last entry —" },
