  "Serebrovasküler hastalıklar": {"AZ":"Serebrovaskulyar xəstəliklər","RU":"Цереброваскулярные заболевания","EN":"Cerebrovascular disease"},
  "Kas gücü kaybı": {"AZ":"Əzələ gücünün itirilməsi","RU":"Снижение мышечной силы","EN":"Loss of muscle strength"},
  "İşitme/görme bozuklukları": {"AZ":"Eşitmə/görmə pozğunluqları","RU":"Нарушения слуха/зрения","EN":"Hearing/visual impairment"},
  "Hastanın güvenliğinin sağlanması": {"AZ":"Xəstənin təhlükəsizliyinin təmin edilməsi","RU":"Обеспечение безопасности пациента","EN":"Patient safety is maintained"},
  "Transfer iki kişiyle, sedye kenarlıkları kaldırılarak güvenli yapılır": {"AZ":"Transfer iki nəfərlə, xərəyin yan qoruyucuları qaldırılaraq təhlükəsiz aparılır","RU":"Перемещение выполняется безопасно, вдвоём, с поднятыми бортиками каталки","EN":"Transfers are done safely by two people with stretcher side rails raised"},
  "Yatak her zaman en alt seviyede tutulur": {"AZ":"Çarpayı həmişə ən aşağı səviyyədə saxlanılır","RU":"Кровать всегда находится в самом нижнем положении","EN":"The bed is always kept in the lowest position"},
  "Konfüzyonu olan hasta için güvenlik önlemleri alınır": {"AZ":"Konfuziyası olan xəstə üçün təhlükəsizlik tədbirləri görülür","RU":"Для пациента со спутанностью сознания принимаются меры безопасности","EN":"Safety measures are taken for a confused patient"},
  "Kullanılan ilaçların düşme riski oluşturup oluşturmadığı kontrol edilir": {"AZ":"İstifadə olunan dərmanların yıxılma riski yaradıb-yaratmadığı yoxlanılır","RU":"Проверяется, повышают ли применяемые препараты риск падения","EN":"Current medications are checked for fall risk"},
  "Ortam aydınlatması yeterli tutulur, geceleri gece lambası kullanılır": {"AZ":"Otağın işıqlandırılması kifayət qədər saxlanılır, gecələr gecə lampası istifadə olunur","RU":"Поддерживается достаточное освещение, ночью используется ночник","EN":"Adequate lighting is maintained; a night light is used at night"},
  "Ortostatik hipotansiyon değerlendirilir, hasta bilgilendirilir": {"AZ":"Ortostatik hipotenziya qiymətləndirilir, xəstə məlumatlandırılır","RU":"Оценивается ортостатическая гипотензия, пациент информируется","EN":"Orthostatic hypotension is assessed and the patient informed"},
  "Tabanı kaymayan ayakkabı önerilir": {"AZ":"Altı sürüşməyən ayaqqabı tövsiyə olunur","RU":"Рекомендуется обувь с нескользящей подошвой","EN":"Non-slip footwear is recommended"},
  "Taburculuk sonrası ev güvenliği konusunda aileye eğitim verilir": {"AZ":"Evə yazıldıqdan sonra ev təhlükəsizliyi barədə ailəyə təlim verilir","RU":"Семье проводится обучение по безопасности дома после выписки","EN":"The family is taught about home safety after discharge"},
  "Uzun yatıştan sonra kademeli mobilizasyon uygulanır": {"AZ":"Uzun müddət yatdıqdan sonra mərhələli mobilizasiya tətbiq olunur","RU":"После длительного постельного режима проводится постепенная мобилизация","EN":"Gradual mobilisation is used after prolonged bed rest"},
  "Yatak kenarlıkları kaldırılır": {"AZ":"Çarpayının yan qoruyucuları qaldırılır","RU":"Бортики кровати поднимаются","EN":"Bed side rails are raised"},
  "Yürümede dengesizlikte baston/koltuk değneği kullanımı öğretilir": {"AZ":"Yerişdə tarazlıq pozulduqda əsa/qoltuq ağacından istifadə öyrədilir","RU":"При неустойчивой походке обучают пользоваться тростью/костылями","EN":"If gait is unsteady, use of a cane/crutches is taught"},
  "Yapılan girişim, eğitim ve gözlemler kayda alınır": {"AZ":"Aparılan müdaxilə, təlim və müşahidələr qeydə alınır","RU":"Выполненные вмешательства, обучение и наблюдения документируются","EN":"Interventions, teaching and observations are documented"},
  "Solunum kaslarında yorgunluk": {"AZ":"Tənəffüs əzələlərinin yorğunluğu","RU":"Утомление дыхательных мышц","EN":"Respiratory muscle fatigue"},
  "Enfeksiyon / akciğer hastalığı": {"AZ":"İnfeksiya / ağciyər xəstəliyi","RU":"Инфекция / заболевание лёгких","EN":"Infection / lung disease"},
  "Oksijen satürasyonu hekimin belirlediği hedefte kalır": {"AZ":"Oksigen saturasiyası həkimin təyin etdiyi hədəfdə qalır","RU":"Сатурация кислорода остаётся в целевом диапазоне, заданном врачом","EN":"Oxygen saturation stays within the physician's target"},
  "Solunum sıkıntısı bulguları azalır": {"AZ":"Tənəffüs çətinliyi əlamətləri azalır","RU":"Признаки дыхательной недостаточности уменьшаются","EN":"Signs of respiratory distress decrease"},
  "Solunum sayısı, derinliği ve SpO₂ izlenecek": {"AZ":"Tənəffüs sayı, dərinliyi və SpO₂ izlənəcək","RU":"Контроль частоты, глубины дыхания и SpO₂","EN":"Monitor respiratory rate, depth and SpO₂"},
  "Hekim istemine göre oksijen tedavisi uygulanacak": {"AZ":"Həkim təyinatına əsasən oksigen terapiyası aparılacaq","RU":"Кислородотерапия по назначению врача","EN":"Give oxygen therapy as ordered by the physician"},
  "Solunum sıkıntısının artması hekime bildirilecek": {"AZ":"Tənəffüs çətinliyinin artması həkimə bildiriləcək","RU":"Об усилении дыхательной недостаточности сообщать врачу","EN":"Report worsening respiratory distress to the physician"},
  "Bilinç değişikliği": {"AZ":"Şüur dəyişikliyi","RU":"Изменение сознания","EN":"Altered consciousness"},
  "Solunum sayısı ve derinliği hasta için belirlenen aralıkta olur": {"AZ":"Tənəffüs sayı və dərinliyi xəstə üçün müəyyən edilmiş aralıqda olur","RU":"Частота и глубина дыхания в пределах, заданных для пациента","EN":"Respiratory rate and depth stay within the range set for the patient"},
  "Derin solunum egzersizleri öğretilecek": {"AZ":"Dərin tənəffüs məşqləri öyrədiləcək","RU":"Обучить упражнениям глубокого дыхания","EN":"Teach deep breathing exercises"},
  "“Solunum sıkıntısı sürüyor; hekim değerlendirdi.”": {"AZ":"“Tənəffüs çətinliyi davam edir; həkim qiymətləndirdi.”","RU":"«Дыхательная недостаточность сохраняется; осмотрен врачом.»","EN":"“Respiratory distress persists; reviewed by physician.”"},
  "“Ek oksijenle satürasyon hedefin altında seyretti, hekime bildirildi.”": {"AZ":"“Əlavə oksigenlə saturasiya hədəfdən aşağı qaldı, həkimə bildirildi.”","RU":"«На дополнительном кислороде сатурация ниже целевой, врач уведомлён.»","EN":"“Saturation stayed below target on supplemental oxygen; physician informed.”"},
