  "Deri bütünlüğü korunur": {"AZ":"Dəri bütövlüyü qorunur","RU":"Целостность кожи сохраняется","EN":"Skin integrity is maintained"},
  "Basınç bölgelerinde kızarıklık gelişmez": {"AZ":"Təzyiq nahiyələrində qızartı yaranmır","RU":"На участках давления не появляется покраснение","EN":"No redness develops over pressure areas"},
  "Bası yarası riski günde {#} kez değerlendirilecek": {"AZ":"Yataq yarası riski gündə {#} dəfə qiymətləndiriləcək","RU":"Оценивать риск пролежней {#} раз(а) в день","EN":"Assess pressure ulcer risk {#} time(s) a day"},
