  "Kimlik belgesi olmadan açılır. Kol bandında geçici protokol no kullanılır; kimlik öğrenilince \"Eşleşme bekleyenler\"den hastane kaydına bağlanır.": {"AZ":"Şəxsiyyət sənədi olmadan açılır. Qolbaqda müvəqqəti protokol nömrəsi istifadə olunur; şəxsiyyət müəyyən edildikdə \"Uyğunlaşdırma gözləyənlər\" bölməsindən xəstəxana qeydinə bağlanır.","RU":"Открывается без документа, удостоверяющего личность. На браслете используется временный номер протокола; после установления личности запись привязывается к больничной записи через раздел «Ожидают сопоставления».","EN":"Opened without an identity document. A temporary protocol no. is used on the wristband; once the identity is known, it is linked to the hospital record from \"Awaiting match\"."},
