  "Eksik ya da hatalı: Ad, Soyad, Cinsiyet, Sorumlu hekim, Yatış nedeni, Doğum tarihi, Onay, Yatak": {"AZ":"Əskik və ya səhv: Ad, Soyad, Cins, Məsul həkim, Yerləşdirmə səbəbi, Doğum tarixi, Təsdiq, Çarpayı","RU":"Не заполнено или неверно: Имя, Фамилия, Пол, Лечащий врач, Причина госпитализации, Дата рождения, Согласие, Койка","EN":"Missing or invalid: First name, Surname, Sex, Responsible physician, Reason for admission, Date of birth, Consent, Bed"},
