  "Klinik kayıtlar (vital bulgular, formlar, skorlar, notlar) bu hastada kalır ve hastane protokolüne bağlanır. Geçici protokol no denetim kaydında saklanır.": {"AZ":"Klinik qeydlər (vital göstəricilər, formalar, şkalalar, qeydlər) bu xəstədə qalır və xəstəxana protokoluna bağlanır. Müvəqqəti protokol nömrəsi audit jurnalında saxlanılır.","RU":"Клинические записи (витальные показатели, формы, шкалы, заметки) остаются у этого пациента и привязываются к больничному протоколу. Временный номер протокола сохраняется в журнале аудита.","EN":"Clinical records (vital signs, forms, scores, notes) stay with this patient and are linked to the hospital protocol. The temporary protocol no. is kept in the audit log."},
